package com.bank.resilient.model;

// Wrapper: either a decoded Transfer or a failure carrying the raw bytes + error.
public class DeserializeResult {
    private final Transfer transfer;   // null if failed
    private final byte[] rawBytes;     // preserved for the DLQ on failure
    private final String error;        // null if ok

    private DeserializeResult(Transfer t, byte[] raw, String error) {
        this.transfer = t; this.rawBytes = raw; this.error = error;
    }
    public static DeserializeResult ok(Transfer t) { return new DeserializeResult(t, null, null); }
    public static DeserializeResult failed(byte[] raw, String error) {
        return new DeserializeResult(null, raw, error);
    }

    public boolean isOk() { return transfer != null; }
    public Transfer getTransfer() { return transfer; }
    public byte[] getRawBytes() { return rawBytes; }
    public String getError() { return error; }
}
