package com.bank.resilient.serde;

import com.bank.resilient.model.DeserializeResult;
import com.bank.resilient.model.Transfer;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;

// Mirrors ErrorHandlingDeserializer: never throws, returns a failure result instead.
public class SafeJsonDeserializer {
    public DeserializeResult deserialize(byte[] data) {
        try {
            String json = new String(data, StandardCharsets.UTF_8);
            // extremely small JSON parse for the demo: {"from":"..","to":"..","amount":..}
            if (!json.trim().startsWith("{")) {
                throw new IllegalArgumentException("not JSON: " + json);
            }
            String from = extract(json, "from");
            String to = extract(json, "to");
            String amt = extract(json, "amount");
            return DeserializeResult.ok(new Transfer(from, to, new BigDecimal(amt)));
        } catch (RuntimeException ex) {
            // DO NOT throw — convert to a handled failure carrying raw bytes.
            return DeserializeResult.failed(data, ex.getMessage());
        }
    }

    private String extract(String json, String field) {
        int i = json.indexOf("\"" + field + "\"");
        if (i < 0) throw new IllegalArgumentException("missing field " + field);
        int colon = json.indexOf(':', i);
        int start = colon + 1;
        while (json.charAt(start) == ' ' || json.charAt(start) == '"') start++;
        int end = start;
        while (end < json.length() && json.charAt(end) != '"'
            && json.charAt(end) != ',' && json.charAt(end) != '}') end++;
        return json.substring(start, end).trim();
    }
}
