package com.bank.resilient.dlq;

import java.nio.charset.StandardCharsets;
import java.util.*;

public class DeadLetterQueue {
    public static class Entry {
        final String rawBytes;
        final String error;
        Entry(byte[] raw, String error) {
            this.rawBytes = new String(raw, StandardCharsets.UTF_8); this.error = error;
        }
        @Override public String toString() { return "DLQ{raw='" + rawBytes + "', error='" + error + "'}"; }
    }
    private final List<Entry> entries = new ArrayList<>();
    public void publish(byte[] raw, String error) { entries.add(new Entry(raw, error)); }
    public List<Entry> getEntries() { return entries; }
}
