package com.bank.resilient.consumer;

import com.bank.resilient.dlq.DeadLetterQueue;
import com.bank.resilient.model.DeserializeResult;
import com.bank.resilient.serde.SafeJsonDeserializer;
import java.util.logging.*;

public class ResilientConsumer {
    private static final Logger log = Logger.getLogger(ResilientConsumer.class.getName());

    private final SafeJsonDeserializer deserializer;
    private final DeadLetterQueue dlq;
    private int processed = 0;

    public ResilientConsumer(SafeJsonDeserializer d, DeadLetterQueue dlq) {
        this.deserializer = d; this.dlq = dlq;
    }

    public void onRawRecord(byte[] data) {
        DeserializeResult result = deserializer.deserialize(data);
        if (!result.isOk()) {
            // Deserialization failure is PERMANENT -> no retry, straight to DLQ, commit past.
            log.severe("Deserialize failed: " + result.getError() + " -> routing to DLQ");
            dlq.publish(result.getRawBytes(), result.getError());
            return;
        }
        process(result.getTransfer());
        processed++;
    }

    private void process(com.bank.resilient.model.Transfer t) {
        log.info(() -> "Processing transfer " + t);
    }

    public int getProcessed() { return processed; }
}
