package com.bank.resilient;

import com.bank.resilient.consumer.ResilientConsumer;
import com.bank.resilient.dlq.DeadLetterQueue;
import com.bank.resilient.serde.SafeJsonDeserializer;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.logging.*;

public class ResilientDemo {
    private static final Logger log = Logger.getLogger(ResilientDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DeadLetterQueue dlq = new DeadLetterQueue();
        ResilientConsumer consumer = new ResilientConsumer(new SafeJsonDeserializer(), dlq);

        List<byte[]> partition = List.of(
            "{\"from\":\"SAV2001\",\"to\":\"CUR3001\",\"amount\":50000}".getBytes(StandardCharsets.UTF_8),
            "THIS IS NOT JSON - upstream misconfig".getBytes(StandardCharsets.UTF_8), // poison
            "{\"from\":\"CUR3001\",\"to\":\"SAV2001\",\"amount\":20000}".getBytes(StandardCharsets.UTF_8));

        for (byte[] rec : partition) consumer.onRawRecord(rec);

        log.info("Processed OK = " + consumer.getProcessed());
        log.info("Dead letter queue:");
        dlq.getEntries().forEach(e -> log.info("  " + e));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
